async def migrate(connection) -> None:
    await connection.execute("""INSERT OR IGNORE INTO patch_notes (slug,title,synopsis,body,version,published_at,discord_announced_at) VALUES ('crafting-and-consumables','Crafting & Consumables','Crafting is here: build Basic weapons into Refined and Masterwork gear, prepare with new raid consumables, and chase stronger Mythical drops.','Crafting introduced\n\nBasic + Basic + 5,000 points creates Refined (+80 damage). Refined + Refined + 25,000 points creates Masterwork (+150 damage). Damaged weapons can still be crafted.\n\nMythical weapons remain non-craftable raid drops and now add +225 damage.\n\nPower Potion now costs 1,500 points. Second Wind grants one additional attack, Berserk grants a one-time 5× attack with heavy recoil, and Blessing of the Gods gives all later stream attacks a 25% boost.\n\nUse !raid help to view the complete shop and raid guide.','8.10.0',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)""")
